# These exact errors/messages were already observed in the independent
# official-original round14 fixture. No other server error is admissible.
INVALID_OPTIONS = (
    ("invalid_mode", '[{"output":"all"},{"additional_args":[{"ik_mode":"bad"}]}]',
     1210, "Incorrect arguments to the ik_mode should be max_word or smart"),
    ("invalid_output", '[{"output":"bad"}]',
     1210, "Incorrect arguments to output mode should be string default or all"),
    ("unknown_ik_option", '[{"additional_args":[{"unknown":1}]}]',
     1235, "ik config not supported"),
)
NULL_OPTIONS = ("[]", '[{"output":"default"}]', '[{"output":"all"}]')
NULL_ERROR = (1235, "ik with the binary charset is not supported")


def load_shared():
    selected = Path(__file__).resolve().with_name("test_tokenize_json_nodes.py")
    if not selected.is_file():
        selected = STAGED_HELPER
    if not selected.is_file():
        raise FileNotFoundError("Install beside test_tokenize_json_nodes.py or provide the selected D: checkout")
    spec = importlib.util.spec_from_file_location("r15_shared_tokenize_json_nodes", selected)
    if spec is None or spec.loader is None:
        raise ImportError("Cannot load the selected shared TOKENIZE regression helper")
    shared = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(shared)
    if shared.OFFICIAL != OFFICIAL or shared.STRICT_MODE != STRICT_MODE:
        raise ValueError("Shared helper official source or strict SQL mode differs")
    return shared


def case(name, sql, params, required_error=None):
    return {"id": name, "sql": sql, "params": list(params), "before": [],
            "allow_error": required_error is not None, "required_error": required_error}


def cases():
    for label, document in DOCUMENTS:
        for mode in MODES:
            for output in OUTPUTS:
                config = json.dumps([{"output": output}, {"additional_args": [{"ik_mode": mode}]}],
                                    ensure_ascii=True, allow_nan=False, separators=(",", ":"))
                for collation in COLLATIONS:
                    yield case(label + "/" + mode + "/" + output + "/" + collation,
                               SELECT_SQL.format(collation=collation), (document, "ik", config))
    for label, config, number, message in INVALID_OPTIONS:
        for collation in COLLATIONS:
            yield case("errors/" + label + "/" + collation,
                       SELECT_SQL.format(collation=collation),
                       ("南京市长江大桥 123个 zxqv", "ik", config),
                       {"number": number, "message": message})
    for index, config in enumerate(NULL_OPTIONS):
        yield case("errors/untyped_null/" + str(index), UNTYPED_SQL, (None, "ik", config),
                   {"number": NULL_ERROR[0], "message": NULL_ERROR[1]})


def workload_hash(workload):
    definition = {"suite": SUITE, "cases": workload, "strict_mode": STRICT_MODE}
    return hashlib.sha256(json.dumps(definition, ensure_ascii=True, allow_nan=False,
                                     separators=(",", ":")).encode("utf-8")).hexdigest()


def check_result(shared, item, result):
    if result.get("id") != item["id"]:
        raise ValueError("Result/case identity mismatch")
    value = result["result"]
    required = item["required_error"]
    if required is None:
        if "error_number" in value:
            raise AssertionError("Unexpected SQL error in required-success case: " + item["id"])
    else:
        shared.compare(required["number"], value.get("error_number"), item["id"] + ".error_number")
        # use_unicode=False preserves binary result cells; PyMySQL error
        # messages remain str, as in the independent original fixture.
        shared.compare(shared.cell(required["message"]), value.get("message"), item["id"] + ".message")
    return result


def capture(shared, options, workload):
    import pymysql
    with pymysql.connect(**options) as connection:
        with connection.cursor() as cursor:
            cursor.execute("SET ob_query_timeout=1000000000")
            cursor.execute("SET SESSION sql_mode=%s", (STRICT_MODE,))
            # Reuse the exact existing query/cell path, including SHOW WARNINGS.
            return [check_result(shared, item, shared.query(cursor, item)) for item in workload]


def read_fixture(path):
    if path.stat().st_size > MAX_COMPRESSED_FIXTURE_BYTES:
        raise ValueError("Compressed fixture exceeds the fixed 32 MiB limit")
    with gzip.GzipFile(fileobj=io.BytesIO(path.read_bytes()), mode="rb") as stream:
        raw = stream.read(MAX_RAW_FIXTURE_BYTES + 1)
    if len(raw) > MAX_RAW_FIXTURE_BYTES:
        raise ValueError("Complete fixture JSON exceeds the fixed 256 MiB limit")
    return json.loads(raw)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", choices=("127.0.0.1", "localhost"), default="127.0.0.1")
    parser.add_argument("--port", type=int, choices=(2891,), default=2891)
    parser.add_argument("--user", default="root")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--record", type=Path, metavar="NEW_PATH")
    mode.add_argument("--expected", type=Path, metavar="EXISTING_FIXTURE")
    parser.add_argument("--record-source-commit")
    parser.add_argument("--record-source-binary-sha256")
    args = parser.parse_args()
    workload = list(cases())
    signature = workload_hash(workload)
    if signature != PINNED_WORKLOAD_SHA256 or len(workload) != EXPECTED_CASE_COUNT:
        raise ValueError("Workload differs from its reviewed fixed definition")
    if len({item["id"] for item in workload}) != EXPECTED_CASE_COUNT:
        raise ValueError("Duplicate case identity")
    if any(len(document.encode("utf-8")) > MAX_INPUT_UTF8_BYTES for _, document in DOCUMENTS):
        raise ValueError("Input exceeds the fixed byte limit; no truncation is permitted")
    if args.record is not None:
        if (os.path.lexists(args.record) or not args.record.parent.is_dir()
                or args.record_source_commit != OFFICIAL
                or args.record_source_binary_sha256 != ORIGINAL_BINARY_SHA256):
            parser.error("--record requires a NEW path, official commit and independently verified exact original binary SHA256")
    elif args.record_source_commit is not None or args.record_source_binary_sha256 is not None:
        parser.error("Provenance options require --record")
    shared = load_shared()
    if args.record is None:
        expected = read_fixture(args.expected)
        if (expected.get("format") != 1 or expected.get("suite") != SUITE
                or expected.get("case_count") != EXPECTED_CASE_COUNT
                or expected.get("workload_sha256") != PINNED_WORKLOAD_SHA256
                or expected.get("original") != {"commit": OFFICIAL, "binary_sha256": ORIGINAL_BINARY_SHA256}
                or [result["id"] for result in expected.get("results", [])] != [item["id"] for item in workload]):
            raise ValueError("Incomplete, unrelated or unverified independent-original fixture")
        for item, result in zip(workload, expected["results"]):
            check_result(shared, item, result)
    actual = capture(shared, dict(host=args.host, port=args.port, user=args.user,
                                 password=os.getenv("SEEKDB_TEST_PASSWORD", ""), charset="utf8mb4",
                                 use_unicode=False, autocommit=True, connect_timeout=10,
                                 read_timeout=180, write_timeout=180), workload)
    if args.record is not None:
        payload = {"format": 1, "suite": SUITE, "case_count": EXPECTED_CASE_COUNT,
                   "workload_sha256": signature,
                   "original": {"commit": OFFICIAL, "binary_sha256": ORIGINAL_BINARY_SHA256},
                   "results": actual}
        raw = (json.dumps(payload, ensure_ascii=True, allow_nan=False,
                          separators=(",", ":")) + "\n").encode("utf-8")
        if len(raw) > MAX_RAW_FIXTURE_BYTES:
            raise ValueError("Complete fixture exceeds 256 MiB; nothing was truncated or written")
        compressed = gzip.compress(raw, mtime=0)
        if len(compressed) > MAX_COMPRESSED_FIXTURE_BYTES:
            raise ValueError("Compressed fixture exceeds 32 MiB; nothing was written")
        with args.record.open("xb") as output:
            output.write(compressed)
        print("RECORDED complete independent-original fixture", args.record)
    else:
        shared.compare(expected["results"], actual)
        print("PASS exact ordered JSON bytes, column metadata, warnings and SQL errors")
    print("cases=", len(actual), "workload_sha256=", signature)


if __name__ == "__main__":
    main()
